        match bad {0=>q.next_full_ticks=4,1=>q.next_full_ticks=12,2=>q.elapsed_ticks+=1,3=>q.state.low[43]=1.,4=>q.controls.mixer_v=f64::NAN,_=>q.settings.attempt_limit=0};
